const data = $input.first().json

// 驗證必要欄位
const errors = [];
if (!data.Topic) errors.push("Topic is required");
if (!data.Topic_Desc || data.Topic_Desc.length < 50) errors.push("Topic_Desc must be > 50 chars");
if (!["Elementary", "Intermediate", "Advanced"].includes(data.Level)) errors.push("Invalid Level");
if (!data.Keywords || data.Keywords.split(",").length < 2) errors.push("Need 2+ keywords");

if (errors.length > 0) {
  throw new Error(errors.join(", "));
}

return [{ json: data }];

const data = $input.first().json;

// ---- 1) Parse Gemini output ----
const textContent = data.content?.parts?.[0]?.text;
if (!textContent) {
  return [{ json: { error: "No text content from Gemini" } }];
}

let parsed;
try {
  parsed = JSON.parse(textContent);
} catch (e) {
  return [{ json: { error: "Failed to parse JSON: " + e.message, raw: textContent } }];
}
if (!Array.isArray(parsed)) parsed = [parsed];

// ---- 2) Build episode_id from Sheets row ----
const sheetRow = $('Edit Fields').first().json.ID;
const episodeId = `ep_${String(sheetRow).padStart(3, '0')}`;

// ---- 3) Speaker mapping ----
const DEFAULT_SPEAKER_MAPPING = {
  Jordan: "Achird",
  Riley: "Kore",
  Tom: "Charon",
  Anna: "Aoede",
  Speaker1: "Achird",
  Speaker2: "Kore",
  Speaker3: "Charon",
  Speaker4: "Aoede",
};

function generateSpeakerConfigs(turns) {
  const unique = new Set();
  (turns || []).forEach(t => t?.speaker && unique.add(t.speaker));
  return Array.from(unique).map(alias => ({
    speakerAlias: alias,
    speakerId: DEFAULT_SPEAKER_MAPPING[alias] || "Kore",
  }));
}

// ---- 4) Convert each section -> ONE item payload for VPS /generate ----
// NOTE: We IGNORE `type` as a routing key. We route by presence of turns/text.
const channel = "bolt_english";

const items = parsed.map((section, idx) => {
  const name = section.section || section.name || "SECTION";

  // Prefer Gemini-provided index if exists; otherwise assign sequential
  const index = Number.isFinite(section.index) ? Number(section.index) : (idx + 1);

  const prompt = section.prompt || "";

  const turns = Array.isArray(section.turns) ? section.turns : [];
  const hasTurns = turns.length > 0;

  let oneSection;

  if (hasTurns) {
    // MULTI
    let speakerConfigs = Array.isArray(section.speaker_configs) ? section.speaker_configs : [];
    if (speakerConfigs.length === 0) {
      speakerConfigs = generateSpeakerConfigs(turns);
    }

    oneSection = {
      name,
      index,
      episode_id: episodeId,
      prompt,
      turns,
      speaker_configs: speakerConfigs,
      // keep `type` if你还想看，但服务端不依赖它
      type: "multi",
    };
  } else {
    // SINGLE
    const text = section.text || "";
    if (!text) {
      // 没 turns 又没 text，这段就是坏数据，直接标记出来
      oneSection = {
        name,
        index,
        episode_id: episodeId,
        error: "Section has neither turns nor text",
        raw: section,
      };
    } else {
      oneSection = {
        name,
        index,
        episode_id: episodeId,
        prompt, // 3.7 single 走 Chirp3-HD 时 prompt 会被忽略，但留着无害
        text,
        // single 模式下我建议你未来传 chirp3-hd 的 voice，不要再传 Kore/Achird
        // voice: "Charon"
        type: "single",
      };
    }
  }

  // IMPORTANT: output must be exactly what /generate expects, but ONLY one section each time
  return {
    json: {
      channel,
      episode_id: episodeId,
      sections: [oneSection],
    }
  };
});

// This makes n8n output multiple items => downstream HTTP node can "Run Once for Each Item"
return items;

